css:
/* ===== WhatsApp Web clone ===== */
#wa-app{position:fixed;inset:0;z-index:3000;display:flex;overflow:hidden;
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.4}
#wa-app,#wa-app *{box-sizing:border-box;margin:0}
#wa-app a{text-decoration:none}

/* theme tokens */
#wa-app.light{--bg:#d1d7db;--side:#fff;--head:#f0f2f5;--search:#f0f2f5;--searchbg:#fff;--text:#111b21;--sub:#667781;
  --border:#e9edef;--hover:#f5f6f6;--active:#f0f2f5;--bub-in:#fff;--bub-out:#d9fdd3;--foot:#f0f2f5;--accent:#00a884;
  --tick:#8696a0;--blue:#53bdeb;--chatbg:#efeae2;--badge:#25d366;--quote:#f5f5f5;--quotebar:#06cf9c;--icon:#54656f;--dot:rgba(0,0,0,.04)}
#wa-app.dark{--bg:#0b141a;--side:#111b21;--head:#202c33;--search:#202c33;--searchbg:#202c33;--text:#e9edef;--sub:#8696a0;
  --border:#222d34;--hover:#202c33;--active:#2a3942;--bub-in:#202c33;--bub-out:#005c4b;--foot:#202c33;--accent:#00a884;
  --tick:#8696a0;--blue:#53bdeb;--chatbg:#0b141a;--badge:#25d366;--quote:#1d282f;--quotebar:#06cf9c;--icon:#aebac1;--dot:rgba(255,255,255,.03)}

#wa-app{background:var(--bg);color:var(--text)}

/* layout */
.wa-side{width:30%;min-width:300px;max-width:420px;background:var(--side);border-right:1px solid var(--border);display:flex;flex-direction:column}
.wa-main{flex:1;display:flex;flex-direction:column;background:var(--chatbg);position:relative;min-width:0}

/* avatar */
.wa-avatar{width:40px;height:40px;border-radius:50%;flex:0 0 40px;display:flex;align-items:center;justify-content:center;
  color:#fff;font-weight:600;font-size:15px;text-transform:uppercase}
.wa-me{background:#6a7175}

/* sidebar header */
.wa-side-head{height:60px;background:var(--head);display:flex;align-items:center;gap:12px;padding:0 16px;flex:0 0 60px}
.wa-side-title{font-weight:600;font-size:16px;flex:1}
.wa-side-actions{display:flex;gap:4px}
.wa-icon{background:none;border:none;cursor:pointer;color:var(--icon);width:40px;height:40px;border-radius:50%;
  display:flex;align-items:center;justify-content:center;transition:background .15s}
.wa-icon:hover{background:rgba(134,150,160,.15)}
.wa-refresh.spin svg{animation:wa-spin .6s linear}
@keyframes wa-spin{to{transform:rotate(360deg)}}

/* search */
.wa-search-wrap{padding:8px 12px;background:var(--side);position:relative;flex:0 0 auto}
.wa-search-ic{position:absolute;left:28px;top:50%;transform:translateY(-50%);color:var(--sub)}
.wa-search{width:100%;border:none;outline:none;background:var(--searchbg);color:var(--text);
  border-radius:8px;padding:9px 12px 9px 46px;font-size:14px}
#wa-app.light .wa-search{background:#f0f2f5}

/* tabs */
.wa-tabs{display:flex;gap:6px;padding:0 12px 8px;background:var(--side);flex:0 0 auto}
.wa-tab{border:none;background:transparent;color:var(--sub);font-size:13px;font-weight:500;
  padding:6px 12px;border-radius:16px;cursor:pointer;display:inline-flex;align-items:center;gap:6px}
.wa-tab:hover{background:var(--hover)}
.wa-tab-active{background:var(--accent);color:#fff}
.wa-tab-count{background:rgba(0,0,0,.18);color:inherit;font-size:11px;font-weight:700;
  border-radius:10px;padding:1px 6px;display:inline-flex;align-items:center;justify-content:center;min-width:16px}
.wa-tab:not(.wa-tab-active) .wa-tab-count{background:var(--badge);color:#fff}

/* chat list */
.wa-chats{flex:1;overflow-y:auto;overflow-x:hidden}
.wa-empty-list{padding:30px 24px;color:var(--sub);text-align:center;line-height:1.6}
.wa-sec{position:sticky;top:0;z-index:1;display:flex;align-items:center;gap:8px;padding:9px 14px;cursor:pointer;
  background:var(--head);border-bottom:1px solid var(--border);user-select:none;-webkit-user-select:none;
  font-size:11.5px;font-weight:600;letter-spacing:.05em;text-transform:uppercase;color:var(--sub)}
.wa-sec:hover{color:var(--text)}
.wa-sec-ar{display:inline-flex;color:var(--icon);transition:transform .15s ease}
.wa-sec.wa-sec-open .wa-sec-ar{transform:rotate(90deg)}
.wa-sec-t{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.wa-sec-n{background:var(--side);color:var(--sub);border-radius:9px;padding:1px 8px;font-size:11px;letter-spacing:0}
.wa-chat{display:flex;align-items:center;gap:13px;padding:10px 14px;cursor:pointer;border-bottom:1px solid var(--border)}
.wa-chat:hover{background:var(--hover)}
.wa-chat.wa-active{background:var(--active)}
.wa-chat-main{flex:1;min-width:0}
.wa-row1{display:flex;align-items:baseline;justify-content:space-between;gap:8px}
.wa-name{font-size:16px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.wa-time{font-size:12px;color:var(--sub);white-space:nowrap;flex:0 0 auto}
.wa-time-unread{color:var(--badge);font-weight:600}
.wa-row2{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:2px}
.wa-preview{font-size:13.5px;color:var(--sub);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex:1;display:flex;align-items:center}
.wa-preview .wa-pv-tick{color:var(--tick);margin-right:3px;display:inline-flex}
.wa-preview .wa-pv-tick.wa-tk-read{color:var(--blue)}
.wa-pv-tick svg{width:15px;height:15px}
.wa-badge{background:var(--badge);color:#fff;font-size:11px;font-weight:600;min-width:20px;height:20px;border-radius:10px;
  display:flex;align-items:center;justify-content:center;padding:0 6px;flex:0 0 auto}

/* chat view */
.wa-cv{flex:1;display:flex;flex-direction:column;height:100%}
.wa-cv-head{height:60px;background:var(--head);display:flex;align-items:center;gap:13px;padding:0 16px;flex:0 0 60px;z-index:2}
.wa-cv-meta{flex:1;min-width:0}
.wa-cv-name{font-size:16px;font-weight:500}
.wa-cv-sub{font-size:12.5px;color:var(--sub)}
.wa-cv-actions{display:flex;gap:2px}
.wa-back{display:none}

/* messages */
.wa-cv-body{flex:1;overflow-y:auto;padding:18px 7% 12px;background-color:var(--chatbg);
  background-image:radial-gradient(var(--dot) 1.4px,transparent 1.4px);background-size:22px 22px}
.wa-divider{text-align:center;margin:14px 0}
.wa-divider span{background:var(--head);color:var(--sub);font-size:12px;font-weight:500;padding:6px 12px;border-radius:8px;
  box-shadow:0 1px 1px rgba(0,0,0,.08);text-transform:uppercase}
.wa-msg{display:flex;margin:2px 0}
.wa-out{justify-content:flex-end}
.wa-in{justify-content:flex-start}
.wa-bubble{max-width:65%;border-radius:8px;padding:6px 9px 8px;position:relative;box-shadow:0 1px .5px rgba(11,20,26,.13);
  word-wrap:break-word;overflow-wrap:anywhere}
.wa-in .wa-bubble{background:var(--bub-in);border-top-left-radius:0}
.wa-out .wa-bubble{background:var(--bub-out);border-top-right-radius:0}
.wa-txt{white-space:pre-wrap}
.wa-txt a{color:#027eb5}
#wa-app.dark .wa-txt a{color:#53bdeb}
.wa-meta{float:right;margin:6px 0 -2px 10px;font-size:11px;color:var(--sub);display:inline-flex;align-items:center;gap:3px;user-select:none}
.wa-sender{color:var(--accent);font-weight:600;font-size:12.5px;margin-bottom:2px}
.wa-tick{display:inline-flex;color:var(--tick)}
.wa-tick.wa-tk-read{color:var(--blue)}
.wa-tick.wa-tk-fail{color:#f15c6d}
.wa-msg-failed{cursor:pointer}
.wa-msg-failed .wa-bubble{outline:1px solid rgba(241,92,109,.4)}

/* quoted reply */
.wa-quote{background:var(--quote);border-left:4px solid var(--quotebar);border-radius:5px;padding:4px 8px;margin-bottom:4px;
  display:flex;flex-direction:column;font-size:13px;overflow:hidden}
.wa-quote-who{color:var(--quotebar);font-weight:600;font-size:12.5px}
.wa-quote-body{color:var(--sub);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

/* media */
.wa-media img{max-width:100%;max-height:330px;border-radius:6px;display:block;cursor:pointer}
.wa-cap{margin-top:4px;white-space:pre-wrap}
.wa-file{display:flex;align-items:center;gap:10px;background:rgba(0,0,0,.05);padding:10px 12px;border-radius:8px;color:inherit}
#wa-app.dark .wa-file{background:rgba(255,255,255,.06)}
.wa-file-name{font-size:13.5px;word-break:break-all}
.wa-cv-body audio{width:100%;margin:2px 0}

/* footer / composer */
.wa-cv-foot{min-height:62px;background:var(--foot);display:flex;align-items:flex-end;gap:10px;padding:8px 16px;flex:0 0 auto}
.wa-cv-foot textarea{flex:1;resize:none;border:none;outline:none;background:var(--searchbg);color:var(--text);
  border-radius:8px;padding:11px 14px;font-size:14.5px;font-family:inherit;max-height:120px;line-height:1.4}
#wa-app.light .wa-cv-foot textarea{background:#fff}
.wa-send{background:none;border:none;cursor:pointer;color:var(--icon);width:46px;height:46px;border-radius:50%;
  display:flex;align-items:center;justify-content:center;flex:0 0 auto}
.wa-send:hover{background:rgba(134,150,160,.15)}

/* intro pane */
.wa-intro{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;
  padding:40px;border-bottom:6px solid var(--accent)}
.wa-intro-logo{color:var(--accent);opacity:.85;margin-bottom:22px}
.wa-intro-title{font-size:30px;font-weight:300;color:var(--text);margin-bottom:12px}
.wa-intro-sub{font-size:14px;color:var(--sub);max-width:480px;line-height:1.7}
.wa-intro-lock{margin-top:26px;color:var(--sub);font-size:13px;display:flex;align-items:center;gap:6px}

/* toast */
.wa-toast{position:absolute;bottom:80px;left:50%;transform:translate(-50%,20px);background:#202c33;color:#e9edef;
  padding:11px 18px;border-radius:8px;font-size:13.5px;box-shadow:0 4px 16px rgba(0,0,0,.3);opacity:0;transition:.3s;z-index:50;max-width:80%}
.wa-toast.show{opacity:1;transform:translate(-50%,0)}

/* scrollbars */
.wa-chats::-webkit-scrollbar,.wa-cv-body::-webkit-scrollbar{width:7px}
.wa-chats::-webkit-scrollbar-thumb,.wa-cv-body::-webkit-scrollbar-thumb{background:rgba(134,150,160,.4);border-radius:4px}

/* mobile */
@media (max-width:768px){
  .wa-side{width:100%;max-width:none}
  .wa-main{position:absolute;inset:0;transform:translateX(100%);transition:transform .25s;z-index:10}
  #wa-app.wa-show-chat .wa-main{transform:translateX(0)}
  .wa-back{display:flex}
  .wa-bubble{max-width:82%}
}

/* ===== v2: templates, translation, failure reasons, 24h window ===== */
/* template rendering in bubbles */
.wa-tpl{display:flex;flex-direction:column;gap:3px}
.wa-tpl-chip{display:inline-flex;align-items:center;gap:4px;align-self:flex-start;font-size:11px;font-weight:600;
  color:var(--accent);background:rgba(0,168,132,.12);border-radius:6px;padding:2px 7px;margin-bottom:2px}
.wa-tpl-chip svg{width:13px;height:13px}
.wa-tpl-head{font-weight:600;white-space:pre-wrap}
.wa-tpl-body{white-space:pre-wrap}
.wa-tpl-foot{font-size:12px;color:var(--sub);margin-top:2px}

/* per-message translate button */
.wa-bubble{position:relative}
.wa-tr-btn{position:absolute;top:3px;right:3px;border:none;background:rgba(134,150,160,.18);color:var(--icon);
  width:24px;height:24px;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;
  opacity:0;transition:opacity .15s;padding:0}
.wa-bubble:hover .wa-tr-btn{opacity:1}
.wa-tr-btn:hover{background:rgba(134,150,160,.35)}
.wa-tr{margin-top:6px;border-top:1px dashed var(--border);padding-top:5px;clear:both}
.wa-tr-label{display:flex;align-items:center;gap:4px;font-size:10.5px;font-weight:600;color:var(--accent);
  text-transform:uppercase;letter-spacing:.04em;margin-bottom:2px}
.wa-tr-label svg{width:12px;height:12px}
.wa-tr-text{white-space:pre-wrap}
.wa-tr-loading{margin-top:6px;border-top:1px dashed var(--border);padding-top:5px;font-size:12.5px;color:var(--sub);font-style:italic}
.wa-tr-err{margin-top:6px;border-top:1px dashed var(--border);padding-top:5px;font-size:12.5px;color:#e5636d;display:flex;align-items:center;gap:4px}
.wa-tr-err svg{width:14px;height:14px;flex:0 0 auto}

/* failure reason line */
.wa-fail-reason{display:flex;align-items:flex-start;gap:5px;max-width:82%;align-self:flex-end;
  font-size:12px;color:#c0394b;background:rgba(241,92,109,.1);border:1px solid rgba(241,92,109,.28);
  border-radius:7px;padding:5px 9px;margin:2px 0 4px}
.wa-in ~ .wa-fail-reason,.wa-msg.wa-in .wa-fail-reason{align-self:flex-start}
.wa-msg.wa-out{flex-direction:column;align-items:flex-end}
.wa-msg.wa-in{flex-direction:column;align-items:flex-start}
.wa-fail-reason svg{width:14px;height:14px;flex:0 0 auto;margin-top:1px;color:#e5636d}
#wa-app.dark .wa-fail-reason{color:#f3a3ab}
.wa-fail-tpl,.wa-fail-reason button{margin-left:6px;border:none;background:var(--accent);color:#fff;
  border-radius:5px;padding:2px 8px;font-size:11px;font-weight:600;cursor:pointer}
.wa-fail-tpl:hover{filter:brightness(1.05)}

/* header language selector + template button */
.wa-lang-wrap{display:inline-flex;align-items:center;gap:3px;color:var(--icon);background:rgba(134,150,160,.12);
  border-radius:14px;padding:2px 6px 2px 8px;margin-right:2px}
.wa-lang-wrap svg{width:14px;height:14px}
.wa-lang{border:none;outline:none;background:transparent;color:var(--text);font-size:12.5px;cursor:pointer;max-width:110px}
.wa-lang option{color:#111}

/* footer: template button + closed-window notice */
.wa-tplbtn{flex:0 0 auto}
.wa-foot-closed{align-items:stretch}
.wa-foot-notice{display:flex;align-items:center;gap:12px;width:100%;background:rgba(241,182,91,.14);
  border:1px solid rgba(241,182,91,.4);border-radius:10px;padding:10px 14px;font-size:13px;color:var(--text)}
.wa-foot-notice > svg{flex:0 0 auto;color:#c88a1e;width:16px;height:20px}
.wa-foot-notice span{color:var(--sub);font-size:12.5px}
.wa-foot-notice .wa-btn-primary{margin-left:auto}
.wa-btn-primary{display:inline-flex;align-items:center;gap:6px;border:none;background:var(--accent);color:#fff;
  border-radius:8px;padding:9px 16px;font-size:13px;font-weight:600;cursor:pointer;white-space:nowrap}
.wa-btn-primary svg{width:18px;height:18px;fill:#fff}
.wa-btn-primary:hover{filter:brightness(1.05)}
.wa-btn-primary:disabled{opacity:.6;cursor:default}

/* template picker modal */
.wa-modal{position:absolute;inset:0;z-index:4000;background:rgba(11,20,26,.55);display:flex;align-items:center;justify-content:center;padding:20px}
.wa-modal-panel{background:var(--side);color:var(--text);width:min(560px,100%);max-height:82vh;border-radius:12px;
  display:flex;flex-direction:column;overflow:hidden;box-shadow:0 12px 40px rgba(0,0,0,.35)}
.wa-modal-head{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:14px 16px;background:var(--head);font-weight:600}
.wa-modal-search{padding:10px 14px;border-bottom:1px solid var(--border)}
.wa-modal-search input{width:100%;border:none;outline:none;background:var(--searchbg);color:var(--text);border-radius:8px;padding:9px 12px;font-size:14px}
#wa-app.light .wa-modal-search input{background:#f0f2f5}
.wa-modal-body{overflow-y:auto;padding:8px}
.wa-tpl-row{padding:10px 12px;border-radius:8px;cursor:pointer;border:1px solid transparent}
.wa-tpl-row:hover{background:var(--hover);border-color:var(--border)}
.wa-tpl-row-h{display:flex;align-items:baseline;justify-content:space-between;gap:8px}
.wa-tpl-tags{font-size:11px;color:var(--sub);white-space:nowrap;text-transform:uppercase;letter-spacing:.03em}
.wa-tpl-row-p{font-size:12.5px;color:var(--sub);margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.wa-tpl-detail{padding:6px 10px 12px}
.wa-tpl-detail .wa-tpl-head{margin-top:8px}
.wa-tpl-detail .wa-tpl-body{margin-top:6px;background:var(--chatbg);border-radius:8px;padding:10px 12px}
.wa-tpl-detail .wa-tpl-foot{margin-top:4px}
.wa-link{border:none;background:none;color:var(--accent);cursor:pointer;font-size:13px;font-weight:600;padding:6px 4px}
.wa-param-wrap{margin-top:12px}
.wa-param-title{font-size:12px;font-weight:600;color:var(--sub);margin-bottom:6px}
.wa-param{display:flex;flex-direction:column;gap:3px;margin-bottom:8px}
.wa-param span{font-size:11.5px;color:var(--sub)}
.wa-param input{border:1px solid var(--border);outline:none;background:var(--searchbg);color:var(--text);border-radius:6px;padding:8px 10px;font-size:13.5px}
.wa-tpl-detail .wa-btn-primary{margin-top:12px;width:100%;justify-content:center}
.wa-tpl-detail .wa-fail-reason{max-width:none;align-self:stretch;margin-top:10px}

/* ---- reactions ---- */
.wa-msg{position:relative}
.wa-react-btn{position:absolute;bottom:2px;border:none;background:var(--panel,#fff);color:var(--icon,#8696a0);
  width:26px;height:26px;border-radius:50%;display:none;align-items:center;justify-content:center;cursor:pointer;
  box-shadow:0 1px 3px rgba(11,20,26,.18)}
.wa-in .wa-react-btn{left:calc(65% + 8px)}
.wa-out .wa-react-btn{right:calc(65% + 8px)}
.wa-msg:hover .wa-react-btn{display:flex}
.wa-react-btn:hover{color:var(--txt,#111b21)}
.wa-reacts{position:absolute;bottom:-10px;display:flex;gap:3px;z-index:2}
.wa-in .wa-reacts{left:10px}
.wa-out .wa-reacts{right:10px}
.wa-react{border:1px solid var(--border,#e9edef);background:var(--panel,#fff);border-radius:12px;
  padding:1px 6px;font-size:12px;line-height:18px;cursor:pointer;display:flex;align-items:center;gap:3px;
  box-shadow:0 1px 2px rgba(11,20,26,.12)}
.wa-react-mine{border-color:var(--accent,#00a884);background:rgba(0,168,132,.12)}
.wa-react-n{font-size:11px;color:var(--muted,#667781)}
.wa-react-pick{position:fixed;z-index:60;display:flex;gap:2px;padding:5px 7px;border-radius:22px;
  background:var(--panel,#fff);border:1px solid var(--border,#e9edef);box-shadow:0 4px 16px rgba(11,20,26,.2)}
.wa-react-pick button{border:none;background:none;font-size:21px;line-height:1;cursor:pointer;
  padding:3px 4px;border-radius:50%}
.wa-react-pick button:hover{transform:scale(1.25);background:var(--hover,#f0f2f5)}
.wa-react-pick button.wa-react-mine{background:rgba(0,168,132,.16)}

/* ---- emoji keyboard ---- */
.wa-emoji-btn.on{color:var(--accent,#00a884)}
.wa-emoji-pad{position:fixed;z-index:70;width:340px;max-width:calc(100vw - 16px);
  background:var(--panel,#fff);border:1px solid var(--border,#e9edef);border-radius:12px;
  box-shadow:0 8px 28px rgba(11,20,26,.22);display:flex;flex-direction:column;overflow:hidden}
.wa-emoji-search{border:none;border-bottom:1px solid var(--border,#e9edef);padding:9px 12px;
  font-size:13px;background:transparent;color:var(--txt,#111b21);outline:none}
.wa-emoji-body{max-height:260px;overflow-y:auto;padding:6px 8px 10px}
.wa-emoji-grp{font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted,#667781);
  margin:8px 2px 4px;font-weight:600}
.wa-emoji-row{display:grid;grid-template-columns:repeat(8,1fr);gap:2px}
.wa-emoji-row button{border:none;background:none;font-size:20px;line-height:1;cursor:pointer;
  padding:5px 0;border-radius:6px}
.wa-emoji-row button:hover{background:var(--hover,#f0f2f5)}
.wa-emoji-none{padding:18px 12px;text-align:center;color:var(--muted,#667781);font-size:12.5px}

/* ---- new chat ---- */
.wa-newchat-panel .wa-modal-body{padding:14px 16px 16px;display:flex;flex-direction:column;gap:10px}
.wa-nc-hint{font-size:11.5px;color:var(--muted,#667781);margin-top:-4px}
.wa-nc-note{display:flex;gap:8px;align-items:flex-start;font-size:12px;line-height:1.45;
  color:var(--muted,#667781);background:var(--hover,#f0f2f5);border-radius:8px;padding:10px 12px}
.wa-nc-note svg{flex:0 0 auto;margin-top:1px}
.wa-nc-err{color:#d93025;font-size:12px;min-height:14px}
.wa-nc-go{align-self:flex-start}

javascript:
(function () {
  // ============ helpers ============
  function ready(fn){ if(document.readyState!=='loading'){fn();} else {document.addEventListener('DOMContentLoaded',fn);} }
  function csrf(){ try{ if(window.frappe && frappe.csrf_token) return frappe.csrf_token; }catch(e){} return window.csrf_token || ''; }
