    var fields=JSON.stringify(["meta_data"]);
    var url='/api/resource/WhatsApp Notification Log?filters='+encodeURIComponent(filters)+'&fields='+encodeURIComponent(fields)+'&limit_page_length=500&order_by='+encodeURIComponent('creation desc');
    var r=await fetch(url,{headers:{'Accept':'application/json'},credentials:'same-origin'});
    if(!r.ok) return {};
    var j=await r.json(); var rows=j.data||[]; var map={};
    rows.forEach(function(row){
      var md; try{ md=typeof row.meta_data==='string'?JSON.parse(row.meta_data):row.meta_data; }catch(e){ return; }
      var entries=md&&md.entry; if(!entries) return; if(!Array.isArray(entries)) entries=[entries];
