      return [ti.header, ti.body, ti.footer].filter(Boolean).join('\n');
    }
    if(m.content_type==='image') return m.message?stripTags(m.message):'Photo';
    if(m.content_type==='document') return m.message?stripTags(m.message):'Document';
    return stripTags(m.message||'');
  }
  function failReason(m){
    if(statusKind(m)!=='failed') return null;
    var r=m.message_id?state.failReasons[m.message_id]:null;
    if(!r) return {friendly:'Not sent — no reason was recorded by WhatsApp.', code:null};
    var friendly=FAIL_MAP[r.code]||r.details||r.title||'Message could not be delivered.';
    return {friendly:friendly, code:r.code, title:r.title, details:r.details};
  }
  function buildChats(){
    var map={};
    state.byMsgId={};
    state.reactions={};
    // Index every message first: a reaction can be fetched before the message
    // it points at, so the lookup has to be complete before it is used.
    state.msgs.forEach(function(m){ if(m.message_id) state.byMsgId[m.message_id]=m; });
    state.msgs.forEach(function(m){
      var num=normNum(m.type==='Incoming'?m['from']:m.to);
      if(!num) return;
      if(!map[num]) map[num]={num:num,name:'',msgs:[],unread:0,last:null,lastIn:null,lastHuman:null};
      var c=map[num];
      // A reaction is not a message in its own right - WhatsApp shows it tucked
      // under the bubble it points at. It still counts as the contact writing
      // in, so it keeps the 24-hour window open, but it must never become the
      // chat's preview line or an unread count of its own.
      if(m.content_type==='reaction'){
        if(m.reply_to_message_id){
          (state.reactions[m.reply_to_message_id]=state.reactions[m.reply_to_message_id]||[]).push(m);
        }
        if(m.type==='Incoming'){ var rd=parseDate(m.creation); if(!c.lastIn||rd>c.lastIn) c.lastIn=rd; }
        return;
      }
      c.msgs.push(m);
      if(m.type==='Incoming' && m.profile_name) c.name=m.profile_name;
      if(m.type==='Incoming'){ var d=parseDate(m.creation); if(!c.lastIn||d>c.lastIn) c.lastIn=d; }
      if(isUnread(m)) c.unread++;
      if(!isTemplateMsg(m)) c.lastHuman=m;
      c.last=m;
    });
    var arr=Object.keys(map).map(function(k){
      var c=map[k]; if(!c.name) c.name='+'+c.num;
      if(!c.last) return null;
      // A chat is a real conversation if anything in it was typed by a human — an
      // incoming message, or a free-text reply we sent. Chats that only ever received
      // template blasts (visitor/appointment alerts, approvals) are notifications.
      c.section=c.lastHuman?'customers':'alerts';
      // Preview and sort a customer chat on its last HUMAN message, so a host buried
      // under 30 appointment alerts can't outrank someone who actually texted today.
      c.pvMsg=c.lastHuman||c.last;
      c.sortAt=parseDate(c.pvMsg.creation);
      return c;
    }).filter(function(c){ return !!c; });
    arr.sort(function(a,b){
      if(a.section!==b.section) return a.section==='customers'?-1:1;
      return b.sortAt-a.sortAt;
    });
    state.chats=arr;
  }
  function activeChat(){ if(!state.active) return null; for(var i=0;i<state.chats.length;i++){ if(state.chats[i].num===state.active) return state.chats[i]; } return null; }
  function windowState(c){
    if(!c || !c.lastIn) return {open:false, lastIn:null};
    var age=(new Date())-c.lastIn;
    return {open:age<WINDOW_MS, lastIn:c.lastIn, age:age};
  }
  function findMsg(name){ for(var i=0;i<state.msgs.length;i++){ if(state.msgs[i].name===name) return state.msgs[i]; } return null; }
  // Unreplied = a customer chat (not an appointment alert) whose last message
  // is Incoming — i.e. the customer's message hasn't had an outgoing reply yet.
  function isUnrepliedChat(c){ return c.section==='customers' && c.last && c.last.type==='Incoming'; }
  function unrepliedCount(){ var n=0; state.chats.forEach(function(c){ if(isUnrepliedChat(c)) n++; }); return n; }
  // "My Replies" = conversations I started or took part in — any chat where
  // I have at least one outgoing message, regardless of who replies after me.
  function isMineChat(c){
    if(!state.currentUser) return false;
    for(var i=0;i<c.msgs.length;i++){ if(c.msgs[i].type==='Outgoing' && c.msgs[i].owner===state.currentUser) return true; }
    return false;
  }
  function mineCount(){ var n=0; state.chats.forEach(function(c){ if(isMineChat(c)) n++; }); return n; }

  // ============ rendering ============
  function tickHTML(m){
    var k=statusKind(m); if(!k) return '';
    if(k==='pending') return '<span class="wa-tick">'+SVG_CLOCK+'</span>';
    if(k==='failed') return '<span class="wa-tick wa-tk-fail">'+SVG_FAIL+'</span>';
    if(k==='sent') return '<span class="wa-tick">'+SVG_SGL+'</span>';
    if(k==='delivered') return '<span class="wa-tick">'+SVG_DBL+'</span>';
    if(k==='read') return '<span class="wa-tick wa-tk-read">'+SVG_DBL+'</span>';
    return '';
  }
  function previewText(c){
    var m=c.pvMsg||c.last;
    if(isTemplateMsg(m)){
      var ti=templateInfo(m); return '📋 '+((ti.body||ti.name||'Template').replace(/\s+/g,' ').trim());
    }
    if(m.content_type==='image') return '📷 Photo';
    if(m.content_type==='document') return '📄 Document';
    if(m.content_type==='audio') return '🎤 Audio';
    if(m.content_type==='video') return '🎥 Video';
    return (m.message?stripTags(m.message):'').replace(/\s+/g,' ').trim();
  }
  function chatRowHTML(c){
    var m=c.pvMsg||c.last;
    var t=parseDate(m.creation);
    var active=c.num===state.active?' wa-active':'';
    var lastOut=m.type==='Outgoing'?'<span class="wa-pv-tick '+(statusKind(m)==='read'?'wa-tk-read':'')+'">'+(statusKind(m)==='failed'?SVG_FAIL:(statusKind(m)==='sent'||statusKind(m)==='pending'?SVG_SGL:SVG_DBL))+'</span> ':'';
    return '<div class="wa-chat'+active+'" data-num="'+esc(c.num)+'">'
      +'<div class="wa-avatar" style="background:'+avatarColor(c.num)+'">'+esc(initials(c.name[0]==='+'?'':c.name))+'</div>'
      +'<div class="wa-chat-main">'
        +'<div class="wa-row1"><span class="wa-name">'+esc(c.name)+'</span><span class="wa-time'+(c.unread?' wa-time-unread':'')+'">'+fmtTime(t)+'</span></div>'
        +'<div class="wa-row2"><span class="wa-preview">'+lastOut+esc(previewText(c))+'</span>'+(c.unread?'<span class="wa-badge">'+c.unread+'</span>':'')+'</div>'
      +'</div>'
    +'</div>';
  }
  var SECTIONS=[
    {key:'customers', title:'Customer messages'},
    {key:'alerts',    title:'Appointment alerts'}
  ];
  function toggleSection(key){
    state.secCollapsed[key]=!state.secCollapsed[key];
    if(key==='alerts') localStorage.setItem('wa-sec-alerts', state.secCollapsed[key]?'1':'0');
    renderSidebar();
  }
  function renderTabs(){
    if(!els.tabs) return;
    ['all','unreplied','mine'].forEach(function(t){
      var btn=els.tabs.querySelector('[data-tab="'+t+'"]');
      if(btn) btn.classList.toggle('wa-tab-active', state.tab===t);
    });
    var ubadge=els.tabs.querySelector('[data-tab="unreplied"] .wa-tab-count');
    if(ubadge){ var un=unrepliedCount(); ubadge.textContent=un; ubadge.style.display=un?'inline-flex':'none'; }
    var mbadge=els.tabs.querySelector('[data-tab="mine"] .wa-tab-count');
    if(mbadge){ var mn=mineCount(); mbadge.textContent=mn; mbadge.style.display=mn?'inline-flex':'none'; }
  }
  function renderSidebar(){
    renderTabs();
    var q=state.search.toLowerCase();
    var buckets={customers:[],alerts:[]};
    var flat=[]; // used for tabs that cut across sections (unreplied, mine)
    state.chats.forEach(function(c){
      if(q && c.name.toLowerCase().indexOf(q)<0 && c.num.indexOf(q)<0) return;
      if(state.tab==='unreplied'){ if(isUnrepliedChat(c)) flat.push(c); return; }
      if(state.tab==='mine'){ if(isMineChat(c)) flat.push(c); return; }
      (buckets[c.section]||buckets.customers).push(c);
    });
    var html='', shown=0;
    if(state.tab==='unreplied' || state.tab==='mine'){
      // Already filtered to a single flat set — section headers would be
      // redundant noise here.
      flat.forEach(function(c){ html+=chatRowHTML(c); shown++; });
      if(!shown) html='<div class="wa-empty-list">'+(state.tab==='unreplied'?'Nothing unreplied — you\'re all caught up':'No conversations found — you haven\'t sent a message yet')+'</div>';
      els.chats.innerHTML=html;
      return;
    }
    SECTIONS.forEach(function(s){
      var list=buckets[s.key]; if(!list.length) return;
      shown+=list.length;
      // a search must never hide its own matches behind a collapsed header
      var open=!!q || !state.secCollapsed[s.key];
      var un=0; list.forEach(function(c){ un+=c.unread; });
      html+='<div class="wa-sec'+(open?' wa-sec-open':'')+'" data-sec="'+esc(s.key)+'">'
          +'<span class="wa-sec-ar">'+SVG_CHEV+'</span>'
          +'<span class="wa-sec-t">'+esc(s.title)+'</span>'
          +'<span class="wa-sec-n">'+list.length+'</span>'
          +(un?'<span class="wa-badge">'+un+'</span>':'')
        +'</div>';
      if(open) list.forEach(function(c){ html+=chatRowHTML(c); });
    });
    if(!shown) html='<div class="wa-empty-list">No chats found</div>';
    els.chats.innerHTML=html;
  }
  function quotedHTML(m){
    if(!m.is_reply || !m.reply_to_message_id) return '';
    var q=state.byMsgId[m.reply_to_message_id];
    var who = q ? (q.type==='Incoming'?(q.profile_name||'Them'):'You') : '';
    var body = q ? (q.content_type!=='text'? (q.content_type==='image'?'📷 Photo':q.content_type==='document'?'📄 Document':q.content_type) : (q.message||'') ) : 'Original message';
    return '<div class="wa-quote"><span class="wa-quote-who">'+esc(who)+'</span><span class="wa-quote-body">'+esc((''+body).slice(0,120))+'</span></div>';
  }
  function templateHTML(m){
    var ti=templateInfo(m);
    var h='<div class="wa-tpl">';
    h+='<div class="wa-tpl-chip">'+SVG_TPL+'<span>Template'+(ti.category?' · '+esc(ti.category):'')+'</span></div>';
    if(!ti.found){
      h+='<div class="wa-tpl-body">'+(ti.body?'<b>'+esc(ti.name)+'</b><br>'+linkify(ti.body):('<em>Template "'+esc(ti.name)+'" (content not available)</em>'))+'</div></div>';
      return h;
    }
    if(ti.header && ti.header_type==='TEXT') h+='<div class="wa-tpl-head">'+linkify(ti.header)+'</div>';
    else if(ti.header && ti.header_type&&ti.header_type!=='TEXT') h+='<div class="wa-tpl-head">📎 '+esc(ti.header_type.charAt(0)+ti.header_type.slice(1).toLowerCase())+' header</div>';
    h+='<div class="wa-tpl-body wa-txt">'+linkify(ti.body)+'</div>';
    if(ti.footer) h+='<div class="wa-tpl-foot">'+esc(ti.footer)+'</div>';
    h+='</div>';
    return h;
  }
  function bodyHTML(m){
    if(isTemplateMsg(m)) return templateHTML(m);
    var inner='';
    if(m.content_type==='image' && m.attach){
      inner+='<div class="wa-media"><img src="'+esc(m.attach)+'" loading="lazy" onclick="window.open(this.src)"></div>';
      if(m.message) inner+='<div class="wa-cap">'+linkify(m.message)+'</div>';
    } else if(m.content_type==='document' && m.attach){
      var fn=decodeURIComponent((m.attach||'').split('/').pop());
      inner+='<a class="wa-file" href="'+esc(m.attach)+'" target="_blank" rel="noopener">'+SVG_DOC+'<span class="wa-file-name">'+esc(fn)+'</span></a>';
      if(m.message) inner+='<div class="wa-cap">'+linkify(m.message)+'</div>';
    } else if((m.content_type==='audio'||m.content_type==='video') && m.attach){
      inner+=(m.content_type==='audio'?'<audio controls src="'+esc(m.attach)+'"></audio>':'<video controls src="'+esc(m.attach)+'" style="max-width:100%;border-radius:6px"></video>');
      if(m.message) inner+='<div class="wa-cap">'+linkify(m.message)+'</div>';
    } else {
      inner+='<span class="wa-txt">'+linkify(m.message||'')+'</span>';
    }
    return inner;
  }
  var REACTION_CHOICES=['\u{1F44D}','\u2764\uFE0F','\u{1F602}','\u{1F62E}','\u{1F622}','\u{1F64F}','\u2705','\u274C'];

  // The reactions on one message, grouped by emoji the way WhatsApp groups
  // them. Ours are marked so a second click can take one back.
  function reactionsFor(m){
    if(!m.message_id) return [];
    var rows=(state.reactions&&state.reactions[m.message_id])||[];
    var order=[], by={};
    rows.forEach(function(r){
      var e=(r.message||'').trim();
      if(!e) return;                                  // an empty emoji is a removal
      if(!by[e]){ by[e]={emoji:e,count:0,mine:false}; order.push(e); }
      by[e].count++;
      if(r.type==='Outgoing') by[e].mine=true;
    });
    return order.map(function(e){ return by[e]; });
  }
  function reactsHTML(m){
    var rs=reactionsFor(m);
    if(!rs.length) return '';
    return '<div class="wa-reacts">'+rs.map(function(r){
      return '<button class="wa-react'+(r.mine?' wa-react-mine':'')+'" data-mid="'+esc(m.message_id)+'" data-emoji="'+esc(r.emoji)+'" title="'+(r.mine?'Remove your reaction':'React')+'">'
        +esc(r.emoji)+(r.count>1?'<span class="wa-react-n">'+r.count+'</span>':'')+'</button>';
    }).join('')+'</div>';
  }
  function trHTML(m){
    if(!state.trShown[m.name]) return '';
    var key=m.name+'@@'+state.trTarget;
    var c=state.trCache[key];
    var lang=langName(state.trTarget);
    if(!c) return '';
    if(c.loading) return '<div class="wa-tr wa-tr-loading">Translating to '+esc(lang)+'…</div>';
    if(c.error) return '<div class="wa-tr wa-tr-err">'+SVG_WARN+' '+esc(c.error)+'</div>';
    return '<div class="wa-tr"><div class="wa-tr-label">'+SVG_GLOBE+' '+esc(lang)+'</div><div class="wa-tr-text">'+linkify(c.text)+'</div></div>';
  }
  function langName(code){ for(var i=0;i<TR_LANGS.length;i++){ if(TR_LANGS[i][0]===code) return TR_LANGS[i][1]; } return code; }
  function renderMessages(){
    var c=activeChat(); if(!c){ return; }
    var html=''; var lastDay='';
    c.msgs.forEach(function(m){
      var d=parseDate(m.creation); var dl=dayLabel(d);
      if(dl!==lastDay){ lastDay=dl; html+='<div class="wa-divider"><span>'+dl+'</span></div>'; }
      var out=m.type==='Outgoing';
      var failed=statusKind(m)==='failed';
      var canTr=!!plainText(m);
      var fr=failed?failReason(m):null;
      // "Who replied": a shared inbox can have several colleagues sending
      // outgoing messages to the same customer at different times, so every
      // outgoing bubble is labelled with its actual sender (WhatsApp Message's
      // `owner` — the Frappe user who created that message). Incoming messages
      // are always the same single contact (already shown in the header), so
      // no label is needed there.
      var senderHTML=(out && m.owner)?('<div class="wa-sender">'+esc(friendlyName(m.owner))+'</div>'):'';
      html+='<div class="wa-msg '+(out?'wa-out':'wa-in')+(failed?' wa-msg-failed':'')+'" data-name="'+esc(m.name)+'">'
        +'<div class="wa-bubble">'
          +(canTr?'<button class="wa-tr-btn" data-name="'+esc(m.name)+'" title="Translate">'+SVG_GLOBE+'</button>':'')
          +senderHTML
          +quotedHTML(m)
          +bodyHTML(m)
          +'<span class="wa-meta">'+fmtTime(d)+(out?tickHTML(m):'')+'</span>'
          +trHTML(m)
        +'</div>'
        +(m.message_id?'<button class="wa-react-btn" data-mid="'+esc(m.message_id)+'" title="React to this message">'+SVG_SMILE+'</button>':'')
        +reactsHTML(m)
        +(fr?'<div class="wa-fail-reason'+(fr.code===131047?' wa-fail-window':'')+'" data-name="'+esc(m.name)+'">'+SVG_WARN+' <span>'+esc(fr.friendly)+(fr.code?' (code '+fr.code+')':'')+(fr.code===131047?' <button class="wa-fail-tpl" data-num="'+esc(c.num)+'">Use a template</button>':'')+'</span></div>':'')
      +'</div>';
    });
    els.body.innerHTML=html;
    els.body.scrollTop=els.body.scrollHeight;
  }
  function renderHead(){
    var c=activeChat(); if(!c) return;
    var opts=TR_LANGS.map(function(l){ return '<option value="'+l[0]+'"'+(l[0]===state.trTarget?' selected':'')+'>'+esc(l[1])+'</option>'; }).join('');
    els.head.innerHTML='<button class="wa-icon wa-back" title="Back">&#8592;</button>'
      +'<div class="wa-avatar" style="background:'+avatarColor(c.num)+'">'+esc(initials(c.name[0]==='+'?'':c.name))+'</div>'
      +'<div class="wa-cv-meta"><div class="wa-cv-name">'+esc(c.name)+'</div><div class="wa-cv-sub">+'+esc(c.num)+'</div></div>'
      +'<div class="wa-cv-actions">'
        +'<span class="wa-lang-wrap" title="Translate messages into">'+SVG_GLOBE+'<select class="wa-lang">'+opts+'</select></span>'
        +'<button class="wa-icon wa-tpl-open" title="Send a template">'+SVG_TPL+'</button>'
      +'</div>';
    els.head.querySelector('.wa-back').onclick=function(){ state.active=null; root.classList.remove('wa-show-chat'); showPane(); };
    els.head.querySelector('.wa-lang').addEventListener('change',function(){
      state.trTarget=this.value; localStorage.setItem('wa-tr-target',state.trTarget);
      state.trShown={}; renderMessages();
      flash('Translation language: '+langName(state.trTarget));
    });
    els.head.querySelector('.wa-tpl-open').addEventListener('click',function(){ openTemplatePicker(c.num); });
  }
  function renderFooter(){
    var c=activeChat(); if(!c) return;
    var ws=windowState(c);
    // The 20s poll calls this again, and rebuilding the footer replaces the
    // textarea with an empty one - so anything half-typed was being wiped
    // mid-sentence and the caret handed back to a blank field. Nothing in the
    // footer depends on the poll, so leave it alone unless the conversation or
    // the 24-hour window has actually changed.
    var key=c.num+'|'+(ws.open?'open':'closed');
    if(els.foot.dataset.waKey===key && els.foot.firstChild) return;
    els.foot.dataset.waKey=key;
    closeEmojiPad();
    var prevTa=els.foot.querySelector('textarea');
    var draft=prevTa?prevTa.value:'';
    var caret=prevTa?prevTa.selectionStart:null;
    if(ws.open){
      els.foot.className='wa-cv-foot';
      els.foot.innerHTML='<button class="wa-icon wa-emoji-btn" title="Emoji">'+SVG_SMILE+'</button>'
        +'<button class="wa-icon wa-tplbtn" title="Send a template">'+SVG_TPL+'</button>'
        +'<textarea rows="1" placeholder="Type a message"></textarea>'
        +'<button class="wa-send" title="Send">'+SVG_SEND+'</button>';
      var ta=els.foot.querySelector('textarea');
      els.foot.querySelector('.wa-send').addEventListener('click',doSend);
      els.foot.querySelector('.wa-emoji-btn').addEventListener('click',function(e){ e.stopPropagation(); openEmojiPad(this); });
      els.foot.querySelector('.wa-tplbtn').addEventListener('click',function(){ openTemplatePicker(c.num); });
      ta.addEventListener('keydown',function(e){ if(e.key==='Enter' && !e.shiftKey){ e.preventDefault(); doSend(); } });
      ta.addEventListener('input',function(){ this.style.height='auto'; this.style.height=Math.min(this.scrollHeight,120)+'px'; });
      // carry a draft across a genuine re-render (the window closing, say)
      if(draft){
        ta.value=draft;
        ta.style.height='auto'; ta.style.height=Math.min(ta.scrollHeight,120)+'px';
      }
      setTimeout(function(){
        ta.focus();
        if(caret!=null){ try{ ta.setSelectionRange(caret,caret); }catch(e){} }
      },30);
    } else {
      els.foot.className='wa-cv-foot wa-foot-closed';
      var why=ws.lastIn?('The last reply from this contact was '+fmtAge(ws.age)+'.'):('This contact has never replied to you.');
      els.foot.innerHTML='<div class="wa-foot-notice">'+SVG_LOCK+' <div><b>24-hour messaging window is closed.</b><br><span>'+esc(why)+' WhatsApp only allows an approved <b>template</b> message until they reply again.</span></div>'
        +'<button class="wa-btn-primary wa-tplbtn">'+SVG_TPL+' Use a template</button></div>';
      els.foot.querySelector('.wa-tplbtn').addEventListener('click',function(){ openTemplatePicker(c.num); });
    }
  }
  function showPane(){
    var c=activeChat();
    if(c){ els.intro.style.display='none'; els.cv.style.display='flex'; renderHead(); renderMessages(); renderFooter(); }
    else { els.intro.style.display='flex'; els.cv.style.display='none'; }
  }
  // ============ deep link ============
  // Lets an outside notification (the desk toast) or a pasted URL open straight onto
  // one conversation:  /whatsapp?chat=254701814616   (or  /whatsapp#254701814616)
  var pendingLink=null;
  function readDeepLink(){
    var n='';
    try{ n=(new URLSearchParams(location.search)).get('chat')||''; }catch(e){}
    if(!n && location.hash) { try{ n=decodeURIComponent(location.hash.slice(1)); }catch(e){ n=location.hash.slice(1); } }
    return normNum(n);
  }
  function syncUrl(num){
    if(!window.history || !history.replaceState) return;
    try{ history.replaceState(null,'',location.pathname+(num?('?chat='+encodeURIComponent(num)):'')); }catch(e){}
  }
  function applyDeepLink(){
    if(!pendingLink) return;
    var num=pendingLink; pendingLink=null;
    for(var i=0;i<state.chats.length;i++){
      if(state.chats[i].num===num){
        // never land the user on a row hidden inside a collapsed section
        state.secCollapsed[state.chats[i].section]=false;
        selectChat(num);
        return;
      }
    }
    flash('No conversation found for +'+num);
  }
  function selectChat(num){
    state.active=num; root.classList.add('wa-show-chat');
    state.trShown={};
    var c=activeChat();
    if(c && c.unread){
      var toMark=c.msgs.filter(function(m){return isUnread(m) && m.message_id;});
      c.msgs.forEach(function(m){ if(isUnread(m)) m.status='marked as read'; });
      c.unread=0;
      toMark.forEach(function(m){ apiMarkRead(m.name); });
    }
    showPane(); renderSidebar(); syncUrl(num);
  }

  // ============ translation ============
  async function toggleTr(name){
    if(state.trShown[name]){ delete state.trShown[name]; renderMessages(); return; }
    state.trShown[name]=true;
    var m=findMsg(name); if(!m){ return; }
    var key=name+'@@'+state.trTarget;
    if(state.trCache[key] && !state.trCache[key].error){ renderMessages(); return; }
    state.trCache[key]={loading:true}; renderMessages();
    try{
      var txt=plainText(m).slice(0,480);
      state.trCache[key]=await translateApi(txt,state.trTarget);
    }catch(e){ state.trCache[key]={error:e.message||'Translation failed'}; }
    if(state.trShown[name]) renderMessages();
  }

  // ============ send ============
  async function doSend(){
    var c=activeChat(); if(!c) return;
    var ta=els.foot.querySelector('textarea'); if(!ta) return;
    var text=(ta.value||'').trim();
    if(!text) return;
    ta.value=''; ta.style.height='auto';
    var tmp={name:'_tmp'+Date.now(),type:'Outgoing',status:'',message:text,content_type:'text',to:c.num,creation:new Date().toISOString().replace('T',' ').slice(0,23),_pending:true};
    state.msgs.push(tmp); buildChats(); state.active=c.num; renderMessages(); renderSidebar();
    try{
      await apiSend(c.num,text);
      await reload(true);
    }catch(e){
      tmp._pending=false; tmp.status='failed'; renderMessages(); renderSidebar();
      flash('Send failed: '+(e.message||'unknown error'));
    }
  }
