  var emojiPad=null;
  function recentEmoji(){
    try{ return JSON.parse(localStorage.getItem('wa-emoji-recent')||'[]'); }catch(e){ return []; }
  }
  function rememberEmoji(e){
    var r=recentEmoji().filter(function(x){ return x!==e; });
    r.unshift(e);
    try{ localStorage.setItem('wa-emoji-recent', JSON.stringify(r.slice(0,32))); }catch(err){}
