  function closeEmojiPad(){
    if(emojiPad && emojiPad.parentNode) emojiPad.parentNode.removeChild(emojiPad);
    emojiPad=null;
    var b=els.foot&&els.foot.querySelector('.wa-emoji-btn');
    if(b) b.classList.remove('on');
  }
  function emojiPadHTML(filter){
    var groups=EMOJI_GROUPS.map(function(g){
      return {name:g.name, list:(g.name==='Recent'?recentEmoji():g.list)};
    }).filter(function(g){ return g.list.length; });
    if(filter){
      // Search is over the group names, since a curated list carries no
      // keywords - good enough to jump to "food" or "gestures" quickly.
      var f=filter.toLowerCase();
      groups=groups.filter(function(g){ return g.name.toLowerCase().indexOf(f)>-1; });
    }
    if(!groups.length) return '<div class="wa-emoji-none">Nothing matches that.</div>';
    return groups.map(function(g){
      return '<div class="wa-emoji-grp">'+esc(g.name)+'</div><div class="wa-emoji-row">'
        +g.list.map(function(e){ return '<button type="button" data-emoji="'+esc(e)+'">'+esc(e)+'</button>'; }).join('')
        +'</div>';
    }).join('');
  }
  function insertEmoji(e){
    var ta=els.foot.querySelector('textarea'); if(!ta) return;
    var s=ta.selectionStart===null?ta.value.length:ta.selectionStart;
    var t=ta.selectionEnd===null?s:ta.selectionEnd;
    ta.value=ta.value.slice(0,s)+e+ta.value.slice(t);
    var pos=s+e.length;
    ta.focus();
    try{ ta.setSelectionRange(pos,pos); }catch(err){}
    ta.style.height='auto'; ta.style.height=Math.min(ta.scrollHeight,120)+'px';
    rememberEmoji(e);
  }
