  async function doReact(mid,emoji){
    var c=activeChat(); if(!c||!mid) return;
    try{
      await apiSendReaction(c.num,mid,emoji);
      await reload(true);
    }catch(e){
      flash((emoji?'Could not react: ':'Could not remove the reaction: ')+(e.message||'unknown error'));
