  function flash(msg){
    var n=document.createElement('div'); n.className='wa-toast'; n.textContent=msg; root.appendChild(n);
    setTimeout(function(){ n.classList.add('show'); },10);
    setTimeout(function(){ n.classList.remove('show'); setTimeout(function(){ if(n.parentNode)n.parentNode.removeChild(n); },300); },3600);
