  // ============ template picker ============
  function placeholderCount(tpl){
    var mx=0, body=(tpl.template||'')+' '+((tpl.header_type==='TEXT'&&tpl.header)?tpl.header:'');
    var re=/\{\{\s*(\d+)\s*\}\}/g, mm;
    while((mm=re.exec(body))){ mx=Math.max(mx,parseInt(mm[1],10)); }
    return mx;
  }
  function tplParamLabels(tpl){
    var src=tpl.field_names||tpl.sample_values||'';
    return src?src.split(',').map(function(s){return s.trim();}):[];
  }
  function openTemplatePicker(num,onSent){
    var approved=state.templatesList.filter(function(t){ return (t.status||'').toUpperCase()==='APPROVED'; });
    var overlay=document.createElement('div'); overlay.className='wa-modal';
    overlay.innerHTML='<div class="wa-modal-panel">'
      +'<div class="wa-modal-head"><span>Send a template to +'+esc(num)+'</span><button class="wa-icon wa-modal-x">'+SVG_X+'</button></div>'
      +'<div class="wa-modal-search"><input type="text" placeholder="Search templates…" class="wa-tpl-search"></div>'
      +'<div class="wa-modal-body"></div>'
      +'</div>';
    root.appendChild(overlay);
    var body=overlay.querySelector('.wa-modal-body');
    function close(){ if(overlay.parentNode) overlay.parentNode.removeChild(overlay); }
    overlay.addEventListener('click',function(e){ if(e.target===overlay) close(); });
    overlay.querySelector('.wa-modal-x').addEventListener('click',close);

    function renderList(q){
      q=(q||'').toLowerCase();
      var rows=approved.filter(function(t){ return !q || (t.template_name||t.name).toLowerCase().indexOf(q)>=0; });
      if(!rows.length){ body.innerHTML='<div class="wa-empty-list">'+(approved.length?'No templates match.':'No approved templates found.')+'</div>'; return; }
      body.innerHTML=rows.map(function(t){
        var preview=(t.template||'').replace(/\s+/g,' ').trim().slice(0,110);
        return '<div class="wa-tpl-row" data-name="'+esc(t.name)+'">'
          +'<div class="wa-tpl-row-h"><b>'+esc(t.template_name||t.name)+'</b><span class="wa-tpl-tags">'+esc((t.language_code||'')+(t.category?' · '+t.category:''))+'</span></div>'
          +'<div class="wa-tpl-row-p">'+esc(preview)+'</div>'
        +'</div>';
      }).join('');
      Array.prototype.forEach.call(body.querySelectorAll('.wa-tpl-row'),function(row){
        row.addEventListener('click',function(){ showDetail(row.getAttribute('data-name')); });
      });
    }
    function showDetail(name){
      var t=state.templates[name]; if(!t) return;
      var n=placeholderCount(t); var labels=tplParamLabels(t);
      var canParam=!!t.sample_values; // server only injects params when sample_values is set
      var paramN = canParam ? Math.max(n, labels.length) : 0;
      var inputs='';
      for(var i=0;i<paramN;i++){
        var lbl=labels[i]||('Parameter '+(i+1));
        inputs+='<label class="wa-param"><span>{{'+(i+1)+'}} '+esc(lbl)+'</span><input type="text" data-idx="'+(i+1)+'" value="'+esc(labels[i]||'')+'"></label>';
      }
      var warnNoParam = (n>0 && !canParam);
      body.innerHTML='<button class="wa-link wa-tpl-back">&#8592; All templates</button>'
        +'<div class="wa-tpl-detail">'
          +'<div class="wa-tpl-row-h"><b>'+esc(t.template_name||t.name)+'</b><span class="wa-tpl-tags">'+esc((t.language_code||'')+(t.category?' · '+t.category:''))+'</span></div>'
          +((t.header_type==='TEXT'&&t.header)?'<div class="wa-tpl-head">'+esc(t.header)+'</div>':'')
          +'<div class="wa-tpl-body wa-txt">'+esc(t.template||'')+'</div>'
          +(t.footer?'<div class="wa-tpl-foot">'+esc(t.footer)+'</div>':'')
          +(inputs?'<div class="wa-param-wrap"><div class="wa-param-title">Fill in the variables:</div>'+inputs+'</div>':'')
          +(warnNoParam?'<div class="wa-fail-reason">'+SVG_WARN+' <span>This template has '+n+' variable(s) but no sample values are configured in Frappe, so they can\'t be filled here. Sending may fail — configure the template first.</span></div>':'')
          +'<button class="wa-btn-primary wa-tpl-send">'+SVG_SEND+' Send template</button>'
        +'</div>';
      body.querySelector('.wa-tpl-back').addEventListener('click',function(){ renderList(overlay.querySelector('.wa-tpl-search').value); });
      body.querySelector('.wa-tpl-send').addEventListener('click',function(){
        var btn=this; btn.disabled=true; btn.textContent='Sending…';
        var params={};
        Array.prototype.forEach.call(body.querySelectorAll('.wa-param input'),function(inp){ params[inp.getAttribute('data-idx')]=inp.value; });
        apiSendTemplate(num,name,params).then(function(){
          close(); flash('Template sent to +'+num);
          reload(true).then(function(){
            if(onSent) onSent();
          });
        }).catch(function(e){
          btn.disabled=false; btn.innerHTML=SVG_SEND+' Send template';
          flash('Template failed: '+(e.message||'error'));
        });
      });
    }
    overlay.querySelector('.wa-tpl-search').addEventListener('input',function(){ renderList(this.value); });
    renderList('');
    setTimeout(function(){ var s=overlay.querySelector('.wa-tpl-search'); if(s) s.focus(); },30);
  }

  // ============ new chat ============
  // Meta only allows free text inside the 24-hour window that a customer's own
  // message opens. A number that has never written in has no window, so the
  // only lawful way to start is an approved template - this walks straight
  // into the template picker rather than offering a text box that would be
  // rejected.
  function toMsisdn(raw){
    var d=(''+(raw||'')).replace(/[^0-9]/g,'');
    if(!d) return '';
    if(d.indexOf('254')===0) return d;
    if(d.charAt(0)==='0') return '254'+d.slice(1);
    if(d.length===9 && (d.charAt(0)==='7'||d.charAt(0)==='1')) return '254'+d;
    return d;           // already carries another country's code
  }
  function chatFor(num){
    for(var i=0;i<state.chats.length;i++){ if(state.chats[i].num===num) return state.chats[i]; }
    return null;
  }
  function openChat(num){
    state.active=num; renderSidebar(); showPane();
  }
  function openNewChat(){
    var overlay=document.createElement('div'); overlay.className='wa-modal';
    overlay.innerHTML='<div class="wa-modal-panel wa-newchat-panel">'
      +'<div class="wa-modal-head"><span>New chat</span><button class="wa-icon wa-modal-x">'+SVG_X+'</button></div>'
      +'<div class="wa-modal-body">'
        +'<label class="wa-param"><span>Phone number</span>'
        +'<input type="tel" class="wa-nc-num" placeholder="0712 345 678 or 254712345678" autocomplete="off"></label>'
        +'<div class="wa-nc-hint">Kenyan numbers may be typed either way &mdash; they are sent as 254&hellip;</div>'
        +'<div class="wa-nc-note">'+SVG_LOCK+' <span>WhatsApp only allows a free message within 24 hours of the '
        +'contact writing to you. To open a new conversation you must send an approved template, and the '
        +'contact must have agreed to hear from you.</span></div>'
        +'<div class="wa-nc-err"></div>'
        +'<button class="wa-btn-primary wa-nc-go">Continue to templates</button>'
      +'</div></div>';
    root.appendChild(overlay);
    function close(){ if(overlay.parentNode) overlay.parentNode.removeChild(overlay); }
    overlay.addEventListener('click',function(e){ if(e.target===overlay) close(); });
    overlay.querySelector('.wa-modal-x').addEventListener('click',close);
    var input=overlay.querySelector('.wa-nc-num');
    var err=overlay.querySelector('.wa-nc-err');
    function go(){
      var num=toMsisdn(input.value);
      if(num.length<10){ err.textContent='That does not look like a phone number.'; return; }
      var existing=chatFor(num);
      close();
      if(existing){
        // already a conversation - open it and let the 24-hour rule decide
        openChat(num);
        flash('You already have a chat with +'+num);
        return;
      }
      openTemplatePicker(num, function(){ openChat(num); });
    }
    overlay.querySelector('.wa-nc-go').addEventListener('click',go);
    input.addEventListener('keydown',function(e){ if(e.key==='Enter'){ e.preventDefault(); go(); } });
    input.addEventListener('input',function(){ err.textContent=''; });
    setTimeout(function(){ input.focus(); },30);
  }

  // ============ theme ============
  function applyTheme(){ root.classList.remove('light','dark'); root.classList.add(state.theme); var b=els.themeBtn; if(b){ b.innerHTML=state.theme==='dark'?SVG_SUN:SVG_MOON; b.title=state.theme==='dark'?'Light mode':'Dark mode'; } }
  function toggleTheme(){ state.theme=state.theme==='dark'?'light':'dark'; localStorage.setItem('wa-theme',state.theme); applyTheme(); }

  // ============ load ============
  var loadedOnce=false;
  async function loadTemplates(){
    try{
      var list=await apiTemplates();
      state.templatesList=list; state.templates={};
      list.forEach(function(t){ state.templates[t.name]=t; });
    }catch(e){}
  }
  async function reload(keepActive){
    try{
      var res=await Promise.all([apiGet(), apiFailReasons()]);
      state.msgs=res[0]; state.failReasons=res[1]||{};
      buildChats();
      var keep=keepActive?state.active:state.active;
      if(keep){ var still=false; state.chats.forEach(function(c){if(c.num===keep)still=true;}); state.active=still?keep:state.active; }
      renderSidebar();
      if(activeChat()){ renderHead(); renderMessages(); renderFooter(); } else if(state.active){ showPane(); }
      applyDeepLink();
      loadedOnce=true;
    }catch(e){
      if(e.status===403){ els.chats.innerHTML='<div class="wa-empty-list">You must be logged in as a System Manager to view WhatsApp messages.<br><br><a href="/login?redirect-to=/whatsapp" style="color:var(--accent)">Log in &#8594;</a></div>'; }
      else if(!loadedOnce){ els.chats.innerHTML='<div class="wa-empty-list">Could not load messages ('+esc(e.message||e.status||'error')+')</div>'; }
    }
  }

  // ============ skeleton ============
