    els.chats=root.querySelector('.wa-chats');
    els.tabs=root.querySelector('.wa-tabs');
    els.intro=root.querySelector('.wa-intro');
    els.cv=root.querySelector('.wa-cv');
    els.head=root.querySelector('.wa-cv-head');
    els.body=root.querySelector('.wa-cv-body');
    els.foot=root.querySelector('.wa-cv-foot');
    els.themeBtn=root.querySelector('.wa-theme');

    // events
    els.chats.addEventListener('click',function(e){
      var sec=e.target.closest('.wa-sec'); if(sec){ toggleSection(sec.getAttribute('data-sec')); return; }
      var el=e.target.closest('.wa-chat'); if(el) selectChat(el.getAttribute('data-num'));
    });
    els.tabs.addEventListener('click',function(e){ var el=e.target.closest('.wa-tab'); if(el){ state.tab=el.getAttribute('data-tab'); renderSidebar(); } });
    root.querySelector('.wa-search').addEventListener('input',function(e){ state.search=e.target.value; renderSidebar(); });
    els.themeBtn.addEventListener('click',toggleTheme);
    root.querySelector('.wa-newchat').addEventListener('click',openNewChat);
    root.querySelector('.wa-refresh').addEventListener('click',function(){ var b=this; b.classList.add('spin'); reload(true).then(function(){ setTimeout(function(){b.classList.remove('spin');},400); }); });
    els.body.addEventListener('click',function(e){
      var tb=e.target.closest('.wa-tr-btn'); if(tb){ e.stopPropagation(); toggleTr(tb.getAttribute('data-name')); return; }
      var ft=e.target.closest('.wa-fail-tpl'); if(ft){ openTemplatePicker(ft.getAttribute('data-num')); return; }
      var rb=e.target.closest('.wa-react-btn'); if(rb){ e.stopPropagation(); openReactPicker(rb,rb.getAttribute('data-mid')); return; }
      var rc=e.target.closest('.wa-react');
      if(rc){ e.stopPropagation(); doReact(rc.getAttribute('data-mid'), rc.classList.contains('wa-react-mine')?'':rc.getAttribute('data-emoji')); return; }
      closeReactPicker();
    });
    document.addEventListener('click',function(e){
      if(!e.target.closest('.wa-react-pick')) closeReactPicker();
      if(!e.target.closest('.wa-emoji-pad') && !e.target.closest('.wa-emoji-btn')) closeEmojiPad();
    });
    document.addEventListener('keydown',function(e){ if(e.key==='Escape'){ closeReactPicker(); closeEmojiPad(); } });

    pendingLink=readDeepLink();
    applyTheme();
    document.documentElement.style.overflow='hidden'; document.body.style.overflow='hidden';
    getCurrentUser().then(function(u){ state.currentUser=u; renderSidebar(); });
    loadTemplates().then(function(){ reload(false); });
    setInterval(function(){ reload(true); }, 20000);
  }

  ready(build);
})();
